suppressPackageStartupMessages({library(data.table);library(NMF)})
a<-commandArgs(TRUE);code<-a[1];out<-a[2];dir.create(out,recursive=TRUE,showWarnings=FALSE)
# Evaluate only helper definitions, without production orchestration.
p<-parse(file.path(code,'remaining_refits.R'));ev<-new.env(parent=globalenv());for(e in p)if(is.call(e)&&identical(e[[1]],as.name('<-'))&&is.call(e[[3]])&&identical(e[[3]][[1]],as.name('function')))eval(e,ev)
ev$TOP_NODES<-5L;set.seed(19);x<-matrix(runif(10*30),10,30,dimnames=list(paste0('node',1:10),paste0('p',1:30)))
f<-nmf(x,3,method='nsNMF',nrun=1,seed=19,.options='p1');w<-basis(f);colnames(w)<-paste0('CM',1:3)
z<-ev$compare_basis_one_to_one(w,w[,c(2,3,1)],'fixture','same');stopifnot(all(abs(z$cosine_similarity-1)<1e-10),!anyDuplicated(z$matched_module))
z<-ev$compare_basis_one_to_one(w,w[,1:2],'fixture','smaller');stopifnot(sum(is.na(z$matched_module))==1)
root<-file.path(out,'fixture');dir.create(file.path(root,'stable_NMF'),recursive=TRUE,showWarnings=FALSE)
n<-48;ids<-paste0('p',1:n);donor<-paste0('d',rep(1:24,each=2));study<-rep(c('S1','S2'),each=24);g<-rep(rep(c('healthy','disease'),each=12),2)
m<-data.table(covarnet_sample_uid=ids,study_canonical=study,tissue_v2='aorta',covarnet_donor_key=donor);fwrite(m,file.path(root,'CoVarNet_sample_metadata.tsv'),sep='\t')
s<-data.table(analysis_profile_uid=ids,proposed_background_id='G2',group_binary=g,donor_block=donor,main_analysis_scope_candidate='true');fwrite(s,file.path(out,'sidecar.tsv'),sep='\t')
h<-matrix(runif(n*14,.1,1),n,14);h[g=='disease',1]<-h[g=='disease',1]+1;h<-h/rowSums(h);colnames(h)<-sprintf('CM%02d',1:14);fwrite(cbind(data.table(covarnet_sample_uid=ids),as.data.table(h)),file.path(root,'stable_NMF/sample_module_relative_coefficient_K14.tsv'),sep='\t')
b<-matrix(runif(10*14),10,14,dimnames=list(paste0('node',1:10),colnames(h)));fwrite(as.data.table(b,keep.rownames='node'),file.path(root,'stable_NMF/module_node_weights_K14.tsv'),sep='\t')
pr<-matrix(runif(10*n),10,n,dimnames=list(rownames(b),ids));fwrite(as.data.table(pr,keep.rownames='node'),file.path(root,'CoVarNet_node_proportion_of_all_atlas_cells.tsv'),sep='\t')
status<-system2('/usr/bin/env',c('-u','R_HOME','-u','R_LIBS','-u','R_LIBS_SITE','-u','R_LIBS_USER','/usr/bin/Rscript','--vanilla',file.path(code,'associations.R'),root,file.path(out,'sidecar.tsv'),file.path(out,'associations')));stopifnot(status==0)
r<-fread(file.path(out,'associations/disease_within_study_tissue_background.tsv'));stopifnot(all(r$n_donors==12),all(r$status=='ESTIMATED_CR2_SATTERTHWAITE'),all(is.finite(r$p)))
writeLines('PASS: real nsNMF fit; one-to-one equal/smaller-rank matching; repeated donor fixture; study/tissue-stratified association and Spearman meta.',file.path(out,'TEST_PASS.txt'))
